b = pathlib.Path('build.py'); s = b.read_text()
alt = "('p04pos', 'p04t', 0, 'ev_g4')"
neu = "('p04pos', 'p04t', 2, 'ev_g4')"
assert s.count(alt) == 1
b.write_text(s.replace(alt, neu))
print('\nbuild.py  Position 04: Stufe 0 (offen) -> 2 (Größenordnung)')
import re
m = re.search(r"BELEG = \[(.+?)\]\n", pathlib.Path('build.py').read_text(), re.S)
stufen = re.findall(r", (\d), 'ev_g", m.group(1))
print(f'Belegstand jetzt: {"".join(stufen)}  (vorher 1130212301)')
